import { TypedNode } from "./Classes/TypedNode.js";
import { BinaryObjectMarkers } from "./Constants/BinaryObjectMarkers.js";
export class TypedNodes {
    static json(data) {
        return new TypedNode(BinaryObjectMarkers.Json, data);
    }
    static object(data) {
        return new TypedNode(BinaryObjectMarkers.Object, data);
    }
    static array(data) {
        if (!Array.isArray(data))
            throw new Error("Data for array must be an array.");
        return new TypedNode(BinaryObjectMarkers.Array, data);
    }
    static int8(value) {
        return new TypedNode(BinaryObjectMarkers.Int8, value);
    }
    static uIint8(value) {
        return new TypedNode(BinaryObjectMarkers.Uint8, value);
    }
    static int16(value) {
        return new TypedNode(BinaryObjectMarkers.Int16, value);
    }
    static uint16(value) {
        return new TypedNode(BinaryObjectMarkers.Uint16, value);
    }
    static uint32(value) {
        return new TypedNode(BinaryObjectMarkers.Uint32, value);
    }
    static int32(value) {
        return new TypedNode(BinaryObjectMarkers.Int32, value);
    }
    static float32(value) {
        return new TypedNode(BinaryObjectMarkers.Float32, value);
    }
    static float64(value) {
        return new TypedNode(BinaryObjectMarkers.Float64, value);
    }
    static bingInt(value) {
        return new TypedNode(BinaryObjectMarkers.BigInt, value);
    }
    static bigUint(value) {
        return new TypedNode(BinaryObjectMarkers.BigUint, value);
    }
    static boolean(value) {
        return new TypedNode(BinaryObjectMarkers.Boolean, value);
    }
    static undefined() {
        return new TypedNode(BinaryObjectMarkers.Undefined, undefined);
    }
    static null() {
        return new TypedNode(BinaryObjectMarkers.Null, null);
    }
    static arrayBuffer(value) {
        return new TypedNode(BinaryObjectMarkers.ArrayBuffer, value);
    }
    static typedArray(type, value) {
        return new TypedNode(BinaryObjectMarkers.TypedArray, 
        //@ts-ignore
        ArrayBuffer.isView(value) ? value : TypedArrayMap[type].from(value), type);
    }
    static string(value) {
        return new TypedNode(BinaryObjectMarkers.String, value);
    }
}
